<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
  import {page} from '$app/state';
  import {goto} from '$app/navigation';
  import {calendarPeriod,moveCalendarDate,shiftCalendarDate,type CalendarMode} from '@schubert/contracts';
  import type {AppData,Row} from '#lib/client/types.ts';
  import {display,recordName} from '#lib/client/api.ts';
  import Icon from './Icon.svelte';import Status from './Status.svelte';import ReferencePicker from './ReferencePicker.svelte';
  let {data,oncreate}:{data:AppData;oncreate?:(context:{day:string;employeeId?:string})=>void}=$props();let busy=$state(false),error=$state(''),chosenDay=$state(''),chosenAnchor=$state('');
  const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin'}).format(new Date());
  const period=$derived(data.summary?.calendar??calendarPeriod('month',today));
  const mode=$derived(period.mode as CalendarMode),date=$derived(period.date as string),employee=$derived(period.employee??'');
  const assignments=$derived(data.related?.calendar_assignments??data.records??[]);
  const days=$derived(period.days as string[]);
  const activeDay=$derived(chosenAnchor===date&&chosenDay&&days.includes(chosenDay)?chosenDay:date);
  const title=$derived(new Intl.DateTimeFormat('de-DE',mode==='day'?{dateStyle:'long'}:{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z')));
  function key(at:string){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin'}).format(new Date(at));}
  function time(at:string){return new Intl.DateTimeFormat('de-DE',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Berlin'}).format(new Date(at));}
  function onDay(row:Row,day:string){return key(row.starts_at)<=day&&key(new Date(Date.parse(row.ends_at)-1).toISOString())>=day;}
  function timeLabel(row:Row,day:string){return (key(row.starts_at)<day?'Fortsetzung':time(row.starts_at))+' – '+(key(new Date(Date.parse(row.ends_at)-1).toISOString())>day?'mehrtägig':time(row.ends_at));}
  function fullDate(day:string){return new Intl.DateTimeFormat('de-DE',{dateStyle:'full',timeZone:'UTC'}).format(new Date(day+'T12:00:00Z'));}
  function chooseDay(day:string){chosenDay=day;chosenAnchor=date;}
  async function navigate(nextMode=mode,nextDate=date,nextEmployee=employee,nextSelectedDay=nextDate){if(busy)return;busy=true;error='';try{const search=new URLSearchParams(page.url.search);for(const key of ['from','to','cursor','employee_id'])search.delete(key);search.set('mode',nextMode);search.set('date',nextDate);if(nextEmployee)search.set('employee_id',nextEmployee);await goto('/dispatch?'+search,{reset:false});chosenDay=nextSelectedDay;chosenAnchor=nextDate;}catch{error='Der Zeitraum konnte nicht geladen werden. Bitte versuchen Sie es erneut.';}finally{busy=false;}}
</script>
<section class="panel calendar-panel" aria-busy={busy}>
  <header class="panel-header"><div><h2>Einsatzplanung</h2><p>Einsätze im ausgewählten Zeitraum. Filter begrenzen die angezeigten Termine.</p></div><div class="calendar-modes" aria-label="Kalenderansicht">{#each [{key:'day',label:'Tag'},{key:'week',label:'Woche'},{key:'month',label:'Monat'}] as item}<button disabled={busy} aria-pressed={mode===item.key} onclick={()=>navigate(item.key as CalendarMode,activeDay)}>{item.label}</button>{/each}</div></header>
  <div class="calendar-toolbar"><div class="period-controls"><button class="icon-button" disabled={busy} aria-label="Vorheriger Zeitraum" onclick={()=>navigate(mode,moveCalendarDate(mode,date,-1))}><Icon name="back" size={18}/></button><h3 aria-live="polite">{title}</h3><button class="icon-button" disabled={busy} aria-label="Nächster Zeitraum" onclick={()=>navigate(mode,moveCalendarDate(mode,date,1))}><Icon name="arrow" size={18}/></button><button class="btn small" disabled={busy} onclick={()=>navigate(mode,today)}>Heute</button></div><div class="calendar-filters"><div class="field"><label class="sr-only" for="calendar-date">Kalenderdatum</label><input id="calendar-date" type="date" value={activeDay} disabled={busy} onchange={e=>e.currentTarget.value&&navigate(mode,e.currentTarget.value)}/></div><div class="field"><label class="sr-only" for="calendar-team">Mitarbeiter filtern</label><ReferencePicker id="calendar-team" reference="team" initial={data.lookups?.team??[]} value={employee} onchange={value=>navigate(mode,date,value,activeDay)}/></div></div></div>
  {#if period.order||page.url.searchParams.get('order_id')||page.url.searchParams.get('order')}<div class="notice info" role="status">Auftragfilter aktiv: {display(period.order||page.url.searchParams.get('order_id')||page.url.searchParams.get('order'),'order_id',data)}. Angezeigt werden nur Einsätze dieses Auftrags. <a class="text-link" href="/dispatch">Alle Einsätze anzeigen</a></div>{/if}
  {#if error}<div class="notice error" role="alert">{error}<button class="btn small" onclick={()=>navigate()}>Erneut laden</button></div>{/if}
  {#if period.truncated}<div class="notice warning" role="status">Dieser Zeitraum enthält mehr als 1.000 Einsätze. Bitte filtern Sie nach einem Mitarbeiter oder wechseln Sie zur Wochenansicht, um alle Einsätze zu sehen.</div>{/if}
  <div class="calendar-scroll"><div class="calendar-grid" class:month={mode==='month'} class:day={mode==='day'}>
    {#if mode!=='day'}{#each days.slice(0,7).map(day=>new Intl.DateTimeFormat('de-DE',{weekday:'short',timeZone:'UTC'}).format(new Date(day+'T12:00:00Z'))) as weekday}<div class="weekday">{weekday}</div>{/each}{/if}
    {#each days as day}{@const events=assignments.filter(row=>onDay(row,day))}<section class="calendar-day" class:outside={day.slice(0,7)!==date.slice(0,7)&&mode==='month'} class:chosen={activeDay===day&&mode==='month'} class:today={day===today}>
      <button class="day-heading" aria-label={`${fullDate(day)}, ${events.length} Einsätze`} aria-pressed={activeDay===day} disabled={busy} onclick={()=>chooseDay(day)}><span class="day-number">{Number(day.slice(-2))}</span>{#if day===today}<span class="today-label">Heute</span>{/if}{#if mode==='month'&&events.length}<span class="event-count">{events.length}</span>{/if}</button>
      <div class="calendar-events">{#each mode==='month'?events.slice(0,2):events as assignment}<a class="calendar-event" href={`/dispatch/${assignment.id}`}><span class="event-time">{timeLabel(assignment,day)}</span><strong>{recordName(assignment)}</strong><span class="event-person">{display(assignment.employee_id,'employee_id',data)}</span></a>{/each}{#if mode==='month'&&events.length>2}<button class="more-events" disabled={busy} onclick={()=>chooseDay(day)}>+ {events.length-2} weitere</button>{/if}{#if !events.length&&mode!=='month'}<p class="calendar-empty">Keine Einsätze für diese Filter</p>{/if}</div>
      {#if events.length&&mode==='month'}<span class="mobile-event-indicator" aria-hidden="true"></span>{/if}
    </section>{/each}
  </div></div>
  {#if mode==='month'}<section class="day-agenda" aria-label="Einsätze am ausgewählten Tag"><header><div><h3>{fullDate(activeDay)}</h3><span class="small muted">{assignments.filter(row=>onDay(row,activeDay)).length} Einsätze</span></div>{#if oncreate}<button class="btn small" disabled={busy} onclick={()=>oncreate?.({day:activeDay,employeeId:employee||undefined})}><Icon name="plus" size={15}/>Einsatz für diesen Tag anlegen</button>{/if}</header>{#each assignments.filter(row=>onDay(row,activeDay)) as assignment}<a class="agenda-row" href={`/dispatch/${assignment.id}`}><span class="agenda-time">{timeLabel(assignment,activeDay)}</span><div><strong>{recordName(assignment)}</strong><p>{display(assignment.employee_id,'employee_id',data)}{assignment.location?' · '+assignment.location:''}</p></div><Status value={assignment.status}/><Icon name="arrow" size={16}/></a>{:else}<p class="calendar-empty">Keine Einsätze für diese Auswahl. Daraus lässt sich keine freie Teamkapazität ableiten.{oncreate?' Legen Sie einen Einsatz direkt für diesen Tag an.':''}</p>{/each}</section>{:else if oncreate}<div class="day-agenda"><header><h3>{fullDate(activeDay)}</h3><button class="btn small" disabled={busy} onclick={()=>oncreate?.({day:activeDay,employeeId:employee||undefined})}><Icon name="plus" size={15}/>Einsatz für diesen Tag anlegen</button></header></div>{/if}
  <footer class="calendar-footer">{busy?'Zeitraum wird geladen …':`${display(period.from,'date')} bis ${display(shiftCalendarDate(period.to,-1),'date')} · ${period.totalLoaded??assignments.length} geladene Einsätze`}{#if assignments.length>25}<span>Die Liste darunter zeigt die ersten 25 Einträge. Alle geladenen Einsätze sind im Kalender erreichbar.</span>{/if}</footer>
</section>
<style>
  .calendar-panel{margin-bottom:28px}.calendar-panel .panel-header{flex-wrap:wrap;gap:20px}.calendar-modes{display:flex;background:var(--wash);padding:4px;border-radius:10px;gap:2px}.calendar-modes button{border:0;background:transparent;color:var(--muted);padding:9px 16px;min-height:40px;border-radius:7px;font-size:13px}.calendar-modes button[aria-pressed=true]{background:var(--paper);color:var(--ink);box-shadow:0 2px 5px #00000012;font-weight:600}.calendar-toolbar{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;padding:20px 24px}.period-controls{display:flex;align-items:center;gap:8px;min-width:0}.period-controls h3{font-size:18px;letter-spacing:-.02em;font-weight:550;min-width:160px;text-align:center}.calendar-filters{display:flex;gap:10px;flex-wrap:wrap}.calendar-filters .field{min-width:0}.calendar-filters input,.calendar-filters :global(select){font-size:13px;min-height:42px;max-width:220px}.calendar-scroll{overflow:auto}.calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(140px,1fr));border-top:1px solid var(--line)}.calendar-grid.month{grid-template-columns:repeat(7,minmax(0,1fr))}.calendar-grid.day{grid-template-columns:1fr}.weekday{padding:12px;color:var(--muted);font-size:12px;text-align:right;background:var(--wash);border-bottom:1px solid var(--line)}.calendar-day{min-height:150px;min-width:0;border-right:1px solid var(--line);border-bottom:1px solid var(--line);position:relative}.calendar-day:nth-child(7n){border-right:0}.calendar-day.chosen{background:var(--wash)}.calendar-day.outside .day-number{color:var(--muted)}.day-heading{display:flex;align-items:center;gap:6px;width:100%;justify-content:flex-end;border:0;background:transparent;min-height:44px;padding:7px 9px;color:var(--ink);font-size:13px}.day-number{width:28px;height:28px;display:grid;place-items:center;border-radius:50%;font-weight:500}.today .day-number{background:var(--forest);color:var(--on-accent)}.today-label{font-size:11px;color:var(--muted);order:-1}.event-count{display:none}.calendar-events{padding:0 7px 10px;display:grid;gap:5px}.calendar-event{display:grid;gap:3px;background:var(--wash);border:1px solid var(--line);border-radius:7px;padding:8px;min-width:0}.calendar-event:hover{border-color:var(--forest)}.calendar-event strong{font-size:12px;font-weight:550;overflow-wrap:anywhere;line-height:1.4;display:-webkit-box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.event-time,.event-person{font-size:11px;color:var(--muted);overflow-wrap:anywhere;line-height:1.4}.more-events{background:transparent;border:0;color:var(--forest);font-size:12px;text-align:left;min-height:32px;padding:3px 6px}.day-agenda{padding:22px 24px}.day-agenda header{display:flex;align-items:baseline;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:16px}.day-agenda h3{font-size:15px;font-weight:550}.agenda-row{display:flex;gap:18px;align-items:center;padding:15px 0;border-top:1px solid var(--line);font-size:13px}.agenda-row>div{flex:1;min-width:0}.agenda-row strong{font-weight:550;overflow-wrap:anywhere}.agenda-row p{font-size:12px;margin-top:5px}.agenda-time{font-variant-numeric:tabular-nums;color:var(--muted);width:130px;flex:none}.calendar-empty{padding:16px 8px;color:var(--muted);font-size:13px;line-height:1.7}.calendar-footer{padding:15px 24px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}.mobile-event-indicator{display:none}@media(max-width:1100px){.month .event-person{display:none}.month .calendar-event{padding:6px}.month .event-time{font-size:10px}.today-label{display:none}}@media(max-width:760px){.calendar-toolbar{padding:16px;gap:12px}.period-controls{width:100%;gap:3px}.period-controls h3{flex:1;min-width:0;font-size:17px}.calendar-filters{width:100%}.calendar-filters .field{flex:1}.calendar-filters input,.calendar-filters :global(select){width:100%;min-width:0;min-height:44px}.calendar-modes{width:100%}.calendar-modes button{flex:1;min-height:44px}.month .calendar-day{min-height:76px}.month .calendar-events{display:none}.month .day-heading{flex-direction:column;gap:2px;padding:4px 1px;min-height:70px;justify-content:flex-start}.month .event-count{display:block;font-size:10px;color:var(--muted)}.month .mobile-event-indicator{display:block;position:absolute;width:4px;height:4px;background:var(--forest);border-radius:50%;bottom:7px;left:calc(50% - 2px);pointer-events:none}.weekday{padding:12px 4px;text-align:center}.day-agenda{padding:20px 16px}.agenda-row{gap:10px;flex-wrap:wrap}.agenda-time{width:100%;font-size:12px}.agenda-row>div{flex-basis:50%}.calendar-footer{padding:14px 16px;line-height:1.6}}
</style>
